def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    bg = max(set(v for row in grid for v in row),
             key=lambda v: sum(row.count(v) for row in grid))
    twos = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 2]
    cells = [(r, c, grid[r][c]) for r in range(h) for c in range(w)
             if grid[r][c] not in (bg, 2)]

    if not twos or not cells:
        return out

    if len({r for r, c in twos}) == 1:  # horizontal marker
        line = twos[0][0]
        rows = [r for r, c, v in cells]
        if max(rows) < line:
            shift = line - 1 - max(rows)
            eight_row = min(rows) + shift - 1
        else:
            shift = line + 1 - min(rows)
            eight_row = max(rows) + shift + 1
        for r, c, v in cells:
            out[r][c] = bg
        for r, c, v in cells:
            out[r + shift][c] = v
        if 0 <= eight_row < h:
            out[eight_row] = [8] * w

    elif len({c for r, c in twos}) == 1:  # vertical marker
        line = twos[0][1]
        cols = [c for r, c, v in cells]
        if max(cols) < line:
            shift = line - 1 - max(cols)
            eight_col = min(cols) + shift - 1
        else:
            shift = line + 1 - min(cols)
            eight_col = max(cols) + shift + 1
        for r, c, v in cells:
            out[r][c] = bg
        for r, c, v in cells:
            out[r][c + shift] = v
        if 0 <= eight_col < w:
            for r in range(h):
                out[r][eight_col] = 8

    return out
